/** Compact human timestamp: HH:MM today, 昨天/日期 for older turns. */
function formatTs(ts: number): string {
  const d = new Date(ts)
  const now = new Date()
  const hm = `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`
  const sameDay = (a: Date, b: Date) =>
    a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate()
  const yesterday = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 1)
  if (sameDay(d, now)) return hm
  if (sameDay(d, yesterday)) return `昨天 ${hm}`
  if (d.getFullYear() === now.getFullYear()) return `${d.getMonth() + 1}月${d.getDate()}日 ${hm}`
  return `${d.getFullYear()}年${d.getMonth() + 1}月${d.getDate()}日 ${hm}`
}

/** Human seconds → "35 秒" / "1 分 23 秒" style label (locale-aware). */
function formatElapsed(seconds: number, t: (key: SettingsKey) => string): string {
  const s = Math.max(0, Math.floor(seconds))
  if (s < 60) return t('kb.elapsedSec').replace('{s}', String(s))
  const m = Math.floor(s / 60)
  const r = s % 60
  return r > 0
    ? t('kb.elapsedMin').replace('{m}', String(m)).replace('{r}', String(r))
    : t('kb.elapsedMinOnly').replace('{m}', String(m))
}

/** First line of a text block (the collapsed 思考过程 summary). */
function firstLine(text: string): string {
  const nl = text.indexOf('\n')
  return nl === -1 ? text : text.slice(0, nl)
}

/**
 * 思考过程 block above a KB answer — mirrors how DSH answers surface their
 * reasoning: while the query runs it shows the live working process (stage +
 * elapsed + growing thinking text) instead of a blank wait; when finished it
 * collapses to a one-line summary that expands on click, with the answer
 * rendered below it.
 */
function KbThinking({ live, thinking, t }: {
  live?: RagAskProgress | undefined
  thinking?: string | undefined
  t: (key: SettingsKey) => string
}) {
  const [open, setOpen] = useState(false)
  if (live !== undefined) {
    const stageLabel = live.stage === 'generating'
      ? (live.answer !== '' ? t('kb.thinkAnswering') : t('kb.thinkReasoning'))
      : t('kb.thinkSearching')
    return (
      <div className={css.think} data-state="running">
        <div className={css.thinkHead} role="status">
          <span className={css.thinkIcon}><IconThinkOutline14 size={14} /></span>
          <span className={css.thinkTitle}>{t('kb.think')}</span>
          <span className={css.thinkStage}>{stageLabel}</span>
          <span className={css.thinkElapsed}>{formatElapsed(live.elapsed, t)}</span>
          <span className={css.thinkSpin} aria-hidden="true" />
        </div>
        {live.thinking !== '' && <div className={css.thinkBody}>{live.thinking}</div>}
      </div>
    )
  }
  const text = (thinking ?? '').trim()
  if (text === '') return null
  return (
    <div className={css.think} data-state="ok" data-expanded={open || undefined}>
      <button
        type="button"
        className={css.thinkHead}
        onClick={() => setOpen(v => !v)}
        aria-expanded={open}
        aria-label={t('kb.think')}
      >
        <span className={css.thinkChevron}>
          {open ? <IconChevronDownOutline14 size={12} /> : <IconChevronRightOutline14 size={12} />}
        </span>
        <span className={css.thinkIcon}><IconThinkOutline14 size={14} /></span>
        <span className={css.thinkTitle}>{t('kb.think')}</span>
        <span className={css.thinkSummary} title={text}>{firstLine(text)}</span>
      </button>
      {open && <div className={css.thinkBody}>{text}</div>}
    </div>
  )
}

