/** A <select> for LLM/vision: DSH catalog (provider-grouped) + custom configs. */
function ModelCategorySelect({ t, options, customs, current, onSelect }: {
  t: (key: SettingsKey) => string
  options: readonly ModelSelectOption[]
  customs: readonly { name: string; model: string; base_url: string; api_key?: string; dims?: number }[]
  current: string
  onSelect: (model: string, base_url?: string, api_key?: string) => void
}) {
  // Group the DSH catalog by provider for <optgroup>.
  const groups: { provider: string; items: { id: string; name: string }[] }[] = []
  for (const o of options) {
    let g = groups.find(x => x.provider === o.providerName)
    if (!g) { g = { provider: o.providerName || 'DSH', items: [] }; groups.push(g) }
    g.items.push({ id: o.id, name: o.name })
  }
  const inOptions = options.some(o => o.id === current)
  const inCustom = customs.some(c => c.model === current)
  return (
    <select
      className={css.modelsSelect}
      value={inOptions || inCustom ? current : ''}
      onChange={e => {
        const val = e.target.value
        if (!val) return
        const custom = customs.find(c => c.model === val)
        onSelect(val, custom?.base_url, custom?.api_key)
      }}
    >
      {!inOptions && !inCustom && current && <option value="">{current}</option>}
      {groups.map(g => (
        <optgroup key={g.provider} label={g.provider}>
          {g.items.map(item => (
            <option key={item.id} value={item.id}>{item.name}</option>
          ))}
        </optgroup>
      ))}
      {customs.length > 0 && (
        <optgroup label={t('kb.modelAddConfig')}>
          {customs.map(c => (
            <option key={c.model} value={c.model}>{c.name} · {c.model}</option>
          ))}
        </optgroup>
      )}
    </select>
  )
}

/** One downloadable local model row: status chip + download button + 设为默认. */
function LocalModelRow({ t, entry, download, isCurrent, onDownload, onSetDefault }: {
  t: (key: SettingsKey) => string
  entry: RagModelEntry
  download?: { status: string; pct: number; message?: string; error?: string | null } | undefined
  isCurrent: boolean
  onDownload: () => void
  onSetDefault: () => void
}) {
  const busy = download !== undefined && (download.status === 'queued' || download.status === 'downloading')
  const failed = download?.status === 'error'
  const meta = [
    entry.size_hint,
    entry.dims ? `${entry.dims}d` : '',
    entry.status === 'ready' ? (formatBytes(entry.size) || undefined) : undefined,
    entry.status === 'ready' && entry.version ? `v${entry.version}` : undefined,
  ].filter(Boolean).join(' · ')
  return (
    <div className={css.modelsEntry}>
      <div className={css.modelsEntryInfo}>
        <div className={css.modelsEntryName}>
          {entry.name}
          {isCurrent && <span className={css.modelsCurrentTag}>{t('kb.modelCurrent')}</span>}
        </div>
        <div className={css.modelsEntryMeta}>{meta || entry.device_note}</div>
        {entry.device_note && entry.status !== 'ready' && (
          <div className={css.modelsEntryNote}>{entry.device_note}</div>
        )}
        {busy && (
          <div className={css.modelsProgress} role="progressbar" aria-valuenow={Math.round(download.pct)} aria-valuemin={0} aria-valuemax={100}>
            <div className={css.modelsProgressBar} style={{ width: `${Math.min(100, download.pct)}%` }} />
            <span className={css.modelsProgressText}>
              {t('kb.modelDownloading')} {Math.round(download.pct)}%{download.message ? ` · ${download.message}` : ''}
            </span>
          </div>
        )}
        {failed && <div className={css.modelsEntryError}>{t('kb.modelDownloadFail')}：{download?.error}</div>}
      </div>
      <div className={css.modelsEntryActions}>
        {entry.status === 'ready' ? (
          <>
            <span className={css.modelsReadyChip}>{t('kb.modelReady')}</span>
            {!isCurrent && (
              <button type="button" className={css.modelsSetBtn} onClick={onSetDefault}>
                {t('kb.modelSetDefault')}
              </button>
            )}
          </>
        ) : busy ? (
          <span className={css.modelsBusyChip}>{t('kb.modelDownloading')}</span>
        ) : (
          <button
            type="button"
            className={css.modelsDlBtn}
            onClick={onDownload}
            title={entry.device_note}
          >
            <IconDownloadOutline16 size={12} />
            {t('kb.modelDownload')}
          </button>
        )}
      </div>
    </div>
  )
}

