                          {modelsSnap.device.vendor === 'amd' && t('kb.aiModelsDeviceRocm')}
                          {modelsSnap.device.vendor === 'cpu' && t('kb.aiModelsDeviceCpu')}
                          {modelsSnap.device.vendor === 'unknown' && t('kb.aiModelsDeviceUnknown')}
