/**
 * dsh-raganything-kb client half: registers the 知识库 foot action (rendered
 * directly ABOVE the Settings trigger — sidebar.footer.action stacks above
 * sidebar.settings) plus the full-viewport knowledge-base panel it opens.
 *
 * This is the browser bundle of the dsh-raganything-kb plugin. It is
 * completely self-contained: it talks to the sidecar REST API (kb-api.ts,
 * http://<host>:17321), owns its own locale dictionary (raganything NS), and
 * does not depend on ui-settings-general or any other feature package.
 */
import type { Context as ClientContext } from '@deepseek-ai/cordis'
import type {} from '@deepseek-ai/dsh-client-locale/client'
import type {} from '@deepseek-ai/dsh-client-ui-slots'
import { KnowledgeBaseRoot } from './KnowledgeBaseRoot.tsx'
import { en, zh, type SettingsKey } from './locales.ts'

/** Dictionary namespace owned by this plugin (KB panel copy). */
const NS = 'raganything'

declare module '@deepseek-ai/dsh-client-ui-slots' {
  interface LocaleNamespaceMap {
    /** Knowledge-base panel copy namespace. */
    raganything: SettingsKey
  }
}

/** Minimal client view of the Host model catalog (provider-grouped). */
interface KbModelCatalog {
  groups?: readonly { id: string; name: string; models?: readonly { id: string; name: string }[] }[]
}

/** Services required (cordis fiber inject). */
export const inject = ['slots', 'locale', 'remote', 'remote.session']

/**
 * Register the raganything dictionary and the KB foot action.
 * @param ctx - client root context.
 */
export function apply(ctx: ClientContext): void {
  ctx.effect(() => ctx.locale.register(NS, { zh, en }), 'dsh-raganything-kb: dictionaries')

  // The knowledge-base panel reads the Host model catalog through this seat —
  // the same `remote.session.modelCatalog()` source the DSH composer model
  // seat uses — so its selector mirrors DSH settings without a cross-plugin
  // value import (client bundle purity gate).
  const kbInjected = (): { loadModels: () => Promise<KbModelCatalog> } => ({
    loadModels: async () => {
      const response = await ctx.remote.session.modelCatalog()
      if (!response.ok) throw new Error(`${response.error.code}: ${response.error.message}`)
      return response.value
    },
  })

  ctx.slots.inject('sidebar.footer.action', () =>
    ctx.slots.register({
      name: 'sidebar.footer.action',
      id: 'knowledge-base',
      order: 0,
      locale: NS,
      inject: kbInjected,
    }, KnowledgeBaseRoot))
}
