
/**
 * RAG-Anything sidecar REST client for the in-DSH knowledge-base panel.
 *
 * Talks to the dsh-raganything sidecar (FastAPI, default 127.0.0.1:17321):
 *   GET    /health      liveness + init state
 *   GET    /documents   all documents with processing status
 *   POST   /upload      multipart file upload; enqueues an ingest task
 *   POST   /tasks       submit {op, params}; returns {task_id}
 *   GET    /tasks/{id}  poll task status/result
 *
 * The panel degrades gracefully: every fetch is wrapped so an unreachable
 * sidecar yields the demo dataset instead of an error wall, and the UI
 * shows a red "未连接（演示数据）" chip. Browser-side direct calls are
 * enabled by the sidecar's CORS middleware (allow_origins=*).
 */

/** One document as returned by GET /documents. */
export interface RagDoc {
  id: string
  status: 'processed' | 'processing' | 'pending' | 'failed' | 'preprocessed' | string
  title: string
  content_length: number | null
  chunks_count: number | null
  created_at?: string
  updated_at?: string
  error?: string | null
  /** True when the original uploaded file is still on the sidecar (可打开原始文件). */
  has_file?: boolean
}

/** One polling task as returned by GET /tasks/{id}. */
export interface RagTask {
  task_id: string
  op: string
  status: 'pending' | 'running' | 'done' | 'error' | 'cancelled'
  result?: { answer?: string; mode?: string; doc_id?: string; thinking?: string } | null
  error?: string | null
  /** Live progress of a running query: stage + elapsed + growing text. */
  progress?: RagAskProgress | null
}

/** Live progress of one retrieval query (sidecar `task.progress`). */
export interface RagAskProgress {
  stage: string
  message: string
  /** Seconds since the query started. */
  elapsed: number
  /** Streaming chain-of-thought text (grows while the model thinks). */
  thinking: string
  /** Streaming answer text (grows once the model starts answering). */
  answer: string
}

/** Resolve the sidecar base URL: same host the page is served from (LAN), falling back to loopback. */
export function ragBaseUrl(): string {
  const host = typeof location !== 'undefined' && location.hostname
    ? location.hostname
    : '127.0.0.1'
  return `http://${host}:17321`
}

const RAG_TIMEOUT_MS = 20_000

async function ragFetch(path: string, init?: RequestInit, timeoutMs: number = RAG_TIMEOUT_MS): Promise<Response> {
  const controller = new AbortController()
  const timer = window.setTimeout(() => controller.abort(), timeoutMs)
  try {
    return await fetch(`${ragBaseUrl()}${path}`, { ...init, signal: controller.signal })
  } finally {
    window.clearTimeout(timer)
  }
}

/** Live check: reachable AND reporting ok. */
export async function ragHealth(): Promise<{ ok: boolean; initialized: boolean } | null> {
  try {
    const res = await ragFetch('/health')
    if (!res.ok) return null
    const data = (await res.json()) as { ok?: boolean; initialized?: boolean }
    return { ok: data.ok === true, initialized: data.initialized === true }
  } catch {
    return null
  }
}

/** Fetch all documents; null when the sidecar is unreachable. */
export async function ragDocuments(): Promise<RagDoc[] | null> {
  try {
    const res = await ragFetch('/documents')
    if (!res.ok) return null
    const data = (await res.json()) as { documents?: RagDoc[] }
    return data.documents ?? []
  } catch {
    return null
  }
}

/** Submit one task ({op, params}); returns the task id, or null when unreachable. */
export async function ragSubmit(op: string, params: Record<string, unknown>): Promise<string | null> {
  try {
    const res = await ragFetch('/tasks', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ op, params }),
    })
    if (!res.ok) return null
    const data = (await res.json()) as { task_id?: string }
    return data.task_id ?? null
  } catch {
    return null
  }
}

/** Poll a task until terminal; returns the task, or null on network failure.
 *  Every tick passes the current task (with live progress) to onTick. */
export async function ragPollTask(taskId: string, onTick?: (waitedS: number, task?: RagTask) => void, deadlineMs = 150_000): Promise<RagTask | null> {
  const deadline = Date.now() + deadlineMs
  let waited = 0
  while (Date.now() < deadline) {
    try {
      const res = await ragFetch(`/tasks/${taskId}`)
      if (res.ok) {
        const task = (await res.json()) as RagTask
        if (task.status === 'done' || task.status === 'error' || task.status === 'cancelled') return task
        onTick?.(waited, task)
      }
    } catch {
      return null
    }
    waited += 1
    onTick?.(waited)
    await new Promise(resolve => window.setTimeout(resolve, 1200))
  }
  return null
}

/** Run one retrieval query; resolves the answer text, or null on any failure. */
export async function ragAsk(query: string, mode = 'hybrid'): Promise<string | null> {
  const taskId = await ragSubmit('query', { query, mode })
  if (taskId === null) return null
  const task = await ragPollTask(taskId)
  if (task === null || task.status !== 'done' || typeof task.result?.answer !== 'string') return null
  return task.result.answer
}

/**
 * Run one retrieval query with live progress. While the sidecar works (and
 * streams the model's chain-of-thought), `onProgress` receives the growing
 * stage/elapsed/thinking/answer snapshot on every poll tick, so the KB chat
 * can render a live 思考过程 block instead of a blank wait. RAG queries can
 * legitimately take several minutes, so the poll deadline is generous.
 */
export async function ragAskLive(
  query: string,
  mode = 'hybrid',
  onProgress?: (p: RagAskProgress) => void,
  deadlineMs = 900_000,
): Promise<{ answer: string; thinking: string; mode: string } | null> {
  const taskId = await ragSubmit('query', { query, mode })
  if (taskId === null) return null
  const task = await ragPollTask(taskId, (_waited, live) => {
    if (onProgress && live?.progress) onProgress(live.progress)
  }, deadlineMs)
  if (task === null || task.status !== 'done' || typeof task.result?.answer !== 'string') return null
  return {
    answer: task.result.answer,
    thinking: task.result.thinking ?? '',
    mode: task.result.mode ?? mode,
  }
}

/** Ingest raw text under a title; resolves the resulting doc id, or null on failure. */
export async function ragIngestText(text: string, title: string): Promise<string | null> {
  const taskId = await ragSubmit('ingest_text', { text, title })
  if (taskId === null) return null
  const task = await ragPollTask(taskId)
  if (task === null || task.status !== 'done') return null
  return task.result?.doc_id ?? null
}

/**
 * Upload one file (PDF/Office/...) to the sidecar and wait for its ingest task.
 *
 * The sidecar saves the file and runs the parser (MinerU) for non-txt/md
 * formats, which can take minutes on first use. Returns:
 *   true  – ingest task finished (doc now visible in GET /documents)
 *   false – the task errored or timed out
 *   null  – sidecar unreachable / upload rejected
 */
export async function ragUploadFile(
  file: File,
  onTick?: (waitedS: number) => void,
  pollMs = 30 * 60_000,
  parentPath?: string,
): Promise<boolean | null> {
  const form = new FormData()
  form.append('file', file)
  // Optional KB folder ("a/b"); the sidecar records it as the doc's folder.
  if (parentPath) form.append('parent_path', parentPath)
  const res = await ragFetch('/upload', { method: 'POST', body: form }, 120_000)
  if (!res.ok) return null
  const data = (await res.json()) as { task_id?: string }
  if (!data.task_id) return null
  const task = await ragPollTask(data.task_id, onTick, pollMs)
  if (task === null) return null
  return task.status === 'done'
}

/**
 * Fire-and-forget upload: submit the file to the sidecar and return the
 * ingest task id immediately, WITHOUT waiting for the parser to finish.
 *
 * The sidecar registers a "parsing" doc entry right away, so the KB panel
 * shows the file in the list (处理中) while parsing runs in the background;
 * the entry flips to 已入库 once the ingest task settles. Returns
 * {task_id, name, has_original} or null when the sidecar is unreachable.
 */
export async function ragUploadSubmit(
  file: File,
  parentPath?: string,
): Promise<{ task_id: string; name: string; has_original: boolean } | null> {
  const form = new FormData()
  form.append('file', file)
  if (parentPath) form.append('parent_path', parentPath)
  const res = await ragFetch('/upload', { method: 'POST', body: form }, 120_000)
  if (!res.ok) return null
  const data = (await res.json()) as { task_id?: string; name?: string }
  if (!data.task_id) return null
  return { task_id: data.task_id, name: data.name ?? file.name, has_original: true }
}

/** URL of the ORIGINAL uploaded file for a doc (需求2: 打开原始布局文件). */
export function ragDocFileUrl(docId: string, download = false): string {
  return `${ragBaseUrl()}/documents/${encodeURIComponent(docId)}/file${download ? '?download=1' : ''}`
}

/** Fetch the original file of a doc as plain text (txt/md/csv…). Null on failure. */
export async function ragDocFileText(docId: string): Promise<string | null> {
  try {
    const res = await ragFetch(`/documents/${encodeURIComponent(docId)}/file`, undefined, 30_000)
    if (!res.ok) return null
    return await res.text()
  } catch {
    return null
  }
}

