export interface RagDocContent {
  doc_id: string
  content: string
  file_path: string
}

/** Fetch the original document content for a doc_id; null when unreachable or missing. */
export async function ragDocContent(docId: string): Promise<RagDocContent | null> {
  try {
    const res = await ragFetch(`/documents/${encodeURIComponent(docId)}/content`)
    if (!res.ok) return null
    return (await res.json()) as RagDocContent
  } catch {
    return null
  }
}

/** Delete one document by id (returns true on success, false on error, null on unreachable). */
export async function ragDeleteDoc(docId: string): Promise<boolean | null> {
  try {
    const res = await ragFetch(`/documents/${encodeURIComponent(docId)}`, { method: 'DELETE' })
    if (!res.ok) return false
    const data = (await res.json()) as { task_id?: string }
    if (!data.task_id) return false
    const task = await ragPollTask(data.task_id, undefined, 60_000)
    if (task === null) return null
    return task.status === 'done'
  } catch {
    return null
  }
}

