/** Download URL of one workspace file (attachment disposition). */
export function ragWorkspaceDownloadUrl(path: string): string {
  return `${ragBaseUrl()}/workspace/download?path=${encodeURIComponent(path)}`
}

/** One entry of a folder zip package: a sidecar doc or a workspace mirror file. */
export interface FolderDownloadItem {
  kind: 'doc' | 'ws'
  /** Sidecar document id (kind "doc"). */
  doc_id?: string
  /** Absolute workspace file path (kind "ws"). */
  ws_path?: string
  /** Path the file takes inside the zip (folder-relative). */
  label: string
}

/**
 * Ask the sidecar to package one KB folder's files into a zip and download it.
 * Resolves false on any failure (unreachable / empty / missing files).
 */
export async function ragFolderDownload(path: string, name: string, files: FolderDownloadItem[]): Promise<boolean> {
  try {
    const res = await ragFetch('/folders/download', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ path, name, files }),
    }, 180_000)
    if (!res.ok) return false
    const blob = await res.blob()
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = name.toLowerCase().endsWith('.zip') ? name : `${name}.zip`
    document.body.appendChild(a)
    a.click()
    a.remove()
    URL.revokeObjectURL(url)
    return true
  } catch {
    return false
  }
}

/** Trigger a browser download for an attachment-disposition URL (hidden anchor click). */
export function triggerDownload(url: string): void {
  const a = document.createElement('a')
  a.href = url
  a.download = ''
  a.rel = 'noopener'
  document.body.appendChild(a)
  a.click()
  a.remove()
}

/** One file row inside a grouped folder (carries the doc's processing status). */
export interface RagFile {
  name: string
  ext: string
  docId: string
  status: string
  error?: string | null
  /** True when the original uploaded file is available on the sidecar. */
  hasFile?: boolean
}

/** Group documents into sidebar folders by their title's directory prefix. */
export interface RagFolder {
  name: string
  files: RagFile[]
}

export function groupDocsIntoFolders(docs: RagDoc[]): RagFolder[] {
  const groups = new Map<string, RagFolder>()
  for (const doc of docs) {
    const parts = (doc.title || doc.id || '未命名').replace(/\\/g, '/').split('/')
    const folderName = parts.length > 1 ? parts.slice(0, -1).join('/') : '全部文档'
    const base = parts[parts.length - 1] || doc.id || '未命名'
    const match = /\.([A-Za-z0-9]+)$/.exec(base)
    const ext = (match?.[1] ?? 'txt').toLowerCase()
    // Older sidecar uploads carry a collision-avoidance prefix
    // ("1a2b3c4d-name.ext"); display the original file name instead.
    const stripped = /^[0-9a-f]{8}-/.test(base) ? base.slice(9) : base
    const name = match && match[1] ? stripped.slice(0, -(match[1].length + 1)) : stripped
    let folder = groups.get(folderName)
    if (folder === undefined) {
      folder = { name: folderName, files: [] }
      groups.set(folderName, folder)
    }
    folder.files.push({ name, ext, docId: doc.id, status: doc.status, ...(doc.error !== undefined ? { error: doc.error } : {}), hasFile: doc.has_file === true })
  }
  return [...groups.values()]
}

